    Props (p): kind, label, selected, expanded, className. -#}
{%- set v_kind = (p.kind ?? 'file') -%}
{%- set v_label = (p.label ?? null) -%}
{%- set v_selected = (p.selected ?? false) -%}
{%- set v_expanded = (p.expanded ?? false) -%}
{%- set c_2 -%}
  {%- if ui_t(ui_eq(v_kind, 'folder')) %}
    {{ include('ui/lucide-icon/lucide-icon.html.twig', {'p': {'Name': ui_s((ui_t(v_expanded) ? 'chevron-down' : 'chevron-right')), 'Size': 16}}, with_context = false) }}
    {{ include('ui/lucide-icon/lucide-icon.html.twig', {'p': {'Name': 'folder-open', 'Size': 16}}, with_context = false) }}
  {%- else %}
    {{ include('ui/lucide-icon/lucide-icon.html.twig', {'p': {'Name': 'file', 'Size': 16}}, with_context = false) }}
  {%- endif %}
  {%- set c_1 -%}
    {{ ui_text(v_label) }}
  {%- endset -%}
  {{ include('ui/inline/inline.html.twig', {'p': {'Class': 'whitespace-nowrap', 'Attrs': ui_attrs(['data-slot', 'file-tree-label'])}, 'children': c_1}, with_context = false) }}
{%- endset -%}
{{ include('ui/button-plain/button-plain.html.twig', {'p': {'Type': 'button', 'Role': 'treeitem', 'Class': ui_s(ui_cnv([ui_recipe('blocks/recipes/file-tree-item.variants.json', {'kind': v_kind}), (p.className ?? '')])), 'Attrs': ui_attrs(['aria-selected', v_selected, 'tabindex', (ui_t(v_selected) ? 0 : -1), 'aria-expanded', (ui_t(ui_eq(v_kind, 'folder')) ? v_expanded : null), 'data-slot', 'file-tree-item', 'data-kind', v_kind, 'data-state', (ui_t(v_selected) ? 'selected' : 'default')])}, 'children': c_2}, with_context = false) }}
